const body = $input.first().json.body || $input.first().json;

// FILTRO 1: solo call_analyzed
if (body.event !== 'call_analyzed') {
  return [{ json: { enviar: false, motivo_skip: 'Evento no es call_analyzed' } }];
}

const call = body.call || {};
const analysis = call.call_analysis || {};
const extracted = analysis.custom_analysis_data || {};

// FILTRO 2: duración mínima 45 segundos
const duracionMs  = call.duration_ms || 0;
const duracionSeg = Math.round(duracionMs / 1000);
if (duracionSeg < 45) {
  return [{ json: { enviar: false, motivo_skip: `Llamada demasiado corta: ${duracionSeg}s` } }];
}

// FILTRO 3: no es buzón de voz
if (analysis.in_voicemail === true) {
  return [{ json: { enviar: false, motivo_skip: 'Llamada fue a buzón de voz' } }];
}

// FILTRO 4: tiene al menos un dato útil
const nombre   = (extracted['Nombre del cliente'] || '').trim();
const contacto = (extracted['Teléfono o email']   || '').trim();
const motivo   = (extracted['Interés detectado']  || '').trim();

const tieneDatos = (
  (nombre   !== '' && nombre   !== 'No indicado') ||
  (contacto !== '' && contacto !== 'No indicado') ||
  (motivo   !== '' && motivo   !== 'No indicado')
);

if (!tieneDatos) {
  return [{ json: { enviar: false, motivo_skip: 'Sin datos útiles recogidos' } }];
}

// ✅ PASA TODOS LOS FILTROS
const empresa    = (extracted['Empresa']          || 'No indicada').trim();
const interes_ia = (extracted['Interés en IA']    || 'No indicado').trim();
const nivel      = (extracted['Nivel de interés'] || 'no determinado').trim().toLowerCase();

const telefono_llamada = call.from_number || 'No disponible';

const duracion = duracionSeg >= 60
  ? `${Math.floor(duracionSeg/60)}m ${duracionSeg%60}s`
  : `${duracionSeg}s`;

const fecha_hora    = new Date().toLocaleString('es-ES', { timeZone: 'Europe/Madrid' });
const resumen       = analysis.call_summary   || 'Sin resumen';
const sentimiento   = analysis.user_sentiment || 'No determinado';
const exitosa       = analysis.call_successful ? 'Sí' : 'No';
const transcripcion = (call.transcript || 'Sin transcripción')
  .replace(/\n?(Agent:)/g, '<br><b>🤖 Agent:</b>')
  .replace(/\n?(User:)/g, '<br><b>👤 User:</b>')
  .replace(/^<br>/, '')
  .replace(/\n/g, ' ');

const nombreMostrar   = nombre   || 'No indicado';
const motivoMostrar   = motivo   || 'No indicado';
const contactoMostrar = contacto || 'No indicado';

const colorNivel = nivel === 'alto' ? '#27ae60' : nivel === 'medio' ? '#e67e22' : '#95a5a6';

const emojiNivel = nivel === 'alto' ? '🔴' : nivel === 'medio' ? '🟡' : '🟢';
const asunto = `${emojiNivel} Ticket | ${nombreMostrar} | ${empresa} | Interés: ${nivel}`;

const cuerpo = [
  '<div style="font-family:Arial,sans-serif;max-width:620px;margin:0 auto">',
  '<h2 style="color:#1a1a2e;border-bottom:3px solid #3498db;padding-bottom:8px">📞 Nuevo Lead Comercial</h2>',
  '<p style="color:#555">Contacto registrado a través del asistente de voz con IA.</p>',
  `<div style="background:${colorNivel};color:white;padding:10px 16px;border-radius:6px;margin:16px 0;font-size:16px"><b>🎯 Nivel de interés: ${nivel.toUpperCase()}</b></div>`,
  '<h3 style="color:#2c3e50">📋 Datos del contacto</h3>',
  '<table style="font-size:15px;color:#333;border-collapse:collapse;width:100%">',
  `<tr style="border-bottom:1px solid #eee"><td style="padding:8px 20px 8px 0;width:40%"><b>👤 Nombre</b></td><td>${nombreMostrar}</td></tr>`,
  `<tr style="border-bottom:1px solid #eee"><td style="padding:8px 20px 8px 0"><b>🏢 Empresa</b></td><td>${empresa}</td></tr>`,
  `<tr style="border-bottom:1px solid #eee"><td style="padding:8px 20px 8px 0"><b>📱 Teléfono llamada</b></td><td>${telefono_llamada}</td></tr>`,
  `<tr style="border-bottom:1px solid #eee"><td style="padding:8px 20px 8px 0"><b>📧 Contacto dado</b></td><td>${contactoMostrar}</td></tr>`,
  `<tr style="border-bottom:1px solid #eee"><td style="padding:8px 20px 8px 0"><b>💬 Motivo</b></td><td>${motivoMostrar}</td></tr>`,
  `<tr style="border-bottom:1px solid #eee"><td style="padding:8px 20px 8px 0"><b>🤖 Interés en IA</b></td><td>${interes_ia}</td></tr>`,
  '</table>',
  '<h3 style="color:#2c3e50;margin-top:20px">📊 Datos de la llamada</h3>',
  '<table style="font-size:15px;color:#333;border-collapse:collapse;width:100%">',
  `<tr style="border-bottom:1px solid #eee"><td style="padding:8px 20px 8px 0;width:40%"><b>😊 Sentimiento</b></td><td>${sentimiento}</td></tr>`,
  `<tr style="border-bottom:1px solid #eee"><td style="padding:8px 20px 8px 0"><b>✅ Llamada exitosa</b></td><td>${exitosa}</td></tr>`,
  `<tr style="border-bottom:1px solid #eee"><td style="padding:8px 20px 8px 0"><b>⏱ Duración</b></td><td>${duracion}</td></tr>`,
  `<tr style="border-bottom:1px solid #eee"><td style="padding:8px 20px 8px 0"><b>🕐 Fecha/hora</b></td><td>${fecha_hora}</td></tr>`,
  '</table>',
  '<h3 style="color:#2c3e50;margin-top:20px">📝 Resumen IA</h3>',
  `<p style="color:#333;background:#f8f9fa;padding:12px;border-radius:6px;border-left:4px solid #3498db">${resumen}</p>`,
  '<h3 style="color:#2c3e50;margin-top:20px">📄 Transcripción</h3>',
  `<p style="color:#555;background:#f8f9fa;padding:12px;border-radius:6px;white-space:pre-line;font-size:13px">${transcripcion}</p>`,
  '<hr style="border:1px solid #eee;margin-top:20px">',
  '<p style="color:#e74c3c"><b>⚡ Estado: PENDIENTE — Contactar a la brevedad.</b></p>',
  `<p style="color:#aaa;font-size:12px">AI Voice Agent · ${new Date().getFullYear()}</p>`,
  '</div>'
].join('');

return [{ json: { enviar: true, asunto, cuerpo } }];
